    TopModule dut (
        .a(a),
        .b(b),
        .c(c),
        .d(d),
        .e(e),
        .out(out)
    );

    // 3. Stimulus & self-checking
    integer errors = 0;

    // Task to check correctness for a given set of inputs
    task check_outputs(input sa, input sb, input sc, input sd, input se);
        reg [4:0] inputs;
        reg [4:0] arr [24:0];
        reg [24:0] expected;
        integer i, j, idx;
        begin
            a = sa;
            b = sb;
            c = sc;
            d = sd;
            e = se;
            #10; // Wait for propagation

            inputs = {sa, sb, sc, sd, se};

            // Generate the 25 pairwise comparisons in nested order 
